import { getMarkdownTheme, withFileMutationQueue, type ExtensionAPI, type ExtensionContext } from '@oh-my-pi/pi-coding-agent';
import { Container, Image, Markdown } from '@oh-my-pi/pi-tui';
import { Workflow } from '../pi/workflow.mjs';
import { Viewer } from '../pi/viewer.mjs';
import { buildRequest } from '../pi/requests.mjs';
import { ENTRY, Targets, reminder, restore as restoreTargets } from '../pi/stale.mjs';
import { reviewMappings } from './review.mjs';

const HELP = [
  "## figlens",
  "",
  "Ask OMP directly: **\"Build the List views screen from ./design.fig using this project's components.\"**",
  "OMP can find and read the design through MCP. No open command or node ID is needed.",
  "Asking OMP to find copy or a screen searches the .fig directly and stores nothing. For repeated searches, ask it to enable an index for a design and scope: it prepares a local index once (no setup command), reports the job until ready, then reuses it across restarts and hosts. Resetting that index needs your explicit request. Asking where a component, variable, style or image is used lists its exact usages the same way: from the .fig directly, or from that index once enabled. Across every design with an index, it also lists where a library component, style or variable is used, by the library reference that outgoing usages on a layer names. Asking it to follow the changes of a design tracks a scope of that index and lists what changed since the last change it handled; asking it to watch that scope picks up each save while its figlens server runs. Searching by meaning or across languages needs an optional local model that you download yourself; ask OMP to list and set it up with the figlens models tool (nothing is downloaded and no design text leaves the machine), and without one search stays text. Giving it a screenshot, or pointing at a found screen, and asking for screens that look like it searches that index by image once its visual layers are built (experimental; the image is not stored).",
  "",
  "Optional shortcuts:",
  "- `/figlens open [description]` — tell OMP what you know: a file, screen name, purpose or visible text. OMP finds it or asks a recognizable follow-up.",
  "- `/figlens preview [description]` — start the local interactive viewer for a design; OMP resolves names and returns its link.",
  "- `/figlens plan [request]` — plan only the requested region or pages before implementing.",
  "- `/figlens yolo [request]` — plan, implement and verify the requested scope, then clean up only this run's temporary plan, scratch exports and processes after success; e.g. `/figlens yolo Home Screen from ./app.fig in ./web`.",
  "",
  "Advanced: saved selections and reusable component matches (not required to build):",
  "- `/figlens open \"./design files/mobile.fig\" --frame 12:345` — use a known node.",
  "- `/figlens frame` — search within the saved file; add an ID to select it directly.",
  "- `/figlens status` — inspect the saved selection.",
  "- `/figlens map` — propose reusable component matches for the design in this conversation.",
  "- `/figlens review` — review pending proposals across this project; no open required.",
  "- `/figlens close` — stop the viewer and clear the saved selection, keeping reviewed mappings.",
  "",
  "MCP-dependent shortcuts currently report an unverified server. Use local controls below or the shared skill in ordinary conversation.",
  "Mappings are optional. OMP can implement the screen immediately.",
].join('\n');
function result(data: unknown) {
  const text = JSON.stringify(data, null, 2);
  return { content: [{ type: 'text' as const, text }], structuredContent: JSON.parse(text), details: data };
}

function describe(data: Awaited<ReturnType<Workflow['bindings']>>) {
  const priority = (item: typeof data.items[number]) => item.status === 'approved' ? 0 : ('issues' in item && (item.issues.length || item.needsReview.length)) ? 1 : item.status === 'unmatched' ? 3 : 2;
  const listed = [...data.items].sort((a, b) => priority(a) - priority(b)).slice(0, 8);
  const rows = listed.map(item => {
    const target = 'approved' in item ? item.approved[0]?.target.path : undefined;
    const issue = 'issues' in item && item.issues.length ? ' · text needs review' : 'needsReview' in item && item.needsReview.length ? ' · new variant/structure' : '';
    return `- **${item.status}** · ${item.name} (${item.id})${target ? ` → ${target}` : ''}${issue}`;
  });
  const approved = data.items.filter(item => 'approved' in item && item.status === 'approved').slice(0, 3);
  const examples = approved.flatMap(item => 'approved' in item ? [
    `**Reuse: ${item.name}**`, '```', item.approved[0].target.import, item.approved[0].target.example, '```',
  ] : []);
  return [`**${data.name}** · ${data.frame}`, `${data.file} · loaded ${data.items.length} of ${data.total} instances`, '', ...rows,
    ...(data.items.length > listed.length ? [`${data.items.length - listed.length} more loaded instances available through figlens_bindings.`] : []), ...examples,
    ...(data.nextOffset !== null ? [`More instances: call figlens_bindings with offset=${data.nextOffset}.`] : []),
    '', 'Mappings: .figlens/component-mappings.md', 'Mappings are optional. Ask OMP to implement the screen, or /figlens review to decide pending proposals.',
  ].join('\n');
}

export default function figlens(pi: ExtensionAPI) {
  const wrapper = fileURLToPath(new URL('../bin/figlens.js', import.meta.url));
  const bundled = !process.env.FIGLENS_BIN && existsSync(wrapper);
  const binary = process.env.FIGLENS_BIN || (bundled ? process.execPath : 'figlens');
  const prefix = bundled ? [wrapper] : [];
  const z = pi.zod;
  const selection = { file: z.string().min(1).max(4096).optional(), frame: z.string().min(1).max(200).optional() };
  const Target = z.object({ path: z.string().min(1).max(4096), export: z.string().min(1).max(200),
    import: z.string().min(1).max(8000), example: z.string().min(1).max(8000) });
  const owners = new Map<string, { root: string; viewer: Viewer; lifetime: AbortController }>();
  function owner(ctx: ExtensionContext) {
    const id = ctx.sessionManager.getSessionId();
    let current = owners.get(id);
    if (current && current.root !== path.resolve(ctx.cwd)) throw new Error('Session project changed; reload the extension before continuing.');
    if (!current) {
      const lifetime = new AbortController();
      const root = path.resolve(ctx.cwd);
      current = { root, viewer: new Viewer(binary, prefix), lifetime };
      owners.set(id, current);
    }
    return current;
  }
  function project(ctx: ExtensionContext, signal?: AbortSignal) {
    const current = owner(ctx);
    const combined = signal ? AbortSignal.any([current.lifetime.signal, signal]) : current.lifetime.signal;
    return new Workflow(current.root, async (args: string[]) => {
      combined.throwIfAborted();
      const execution = await pi.exec(binary, [...prefix, ...args], { cwd: current.root, signal: combined, timeout: 120000 });
      if (execution.code !== 0 || execution.killed) throw new Error(execution.stderr.trim().slice(0, 2000) || 'CLI cancelled or timed out.');
      return JSON.parse(execution.stdout);
    }, async () => { combined.throwIfAborted(); });
  }
  async function closeOwners() {
    for (const current of owners.values()) current.lifetime.abort();
    await Promise.all([...owners.values()].map(current => current.viewer.close()));
    owners.clear();
  }
  function requireMcp() {
    const names = pi.getAllTools().filter(tool => tool.sourceInfo.source === 'mcp').map(tool => tool.name);
    throw new Error(`MCP shortcut unavailable: OMP does not expose the effective server version or snapshot to extensions. Available MCP tools: ${names.join(', ') || 'none'}. Use the figlens skill directly, or use local preview, frame, status and review commands.`);
  }
  async function sendRequest(kind: string, request: string) {
    requireMcp();
    pi.sendUserMessage(await buildRequest(kind, request, import.meta.url));
  }
  pi.registerMessageRenderer('figlens', message => new Markdown(
    typeof message.content === 'string' ? message.content : JSON.stringify(message.content), 1, 1, getMarkdownTheme(),
  ));
  pi.registerMessageRenderer('figlens-preview', message => {
    const container = new Container();
    for (const part of typeof message.content === 'string' ? [{ type: 'text' as const, text: message.content }] : message.content) {
      if (part.type === 'text') container.addChild(new Markdown(part.text, 1, 0, getMarkdownTheme()));
      else if (part.type === 'image') container.addChild(new Image(part.data, part.mimeType,
        { fallbackColor: text => text }, { maxWidthCells: 80, maxHeightCells: 24 }));
    }
    return container;
  });
  function show(data: unknown, ctx: ExtensionContext) {
    pi.sendMessage({ customType: 'figlens', content: typeof data === 'string' ? data : JSON.stringify(data, null, 2), display: true });
  }

  async function requestScope(request: string) {
    await sendRequest('open', request);
  }

  async function preview(design: Awaited<ReturnType<Workflow['design']>>, ctx: ExtensionContext) {
    const directory = await project(ctx).referenceDirectory();
    await mkdir(directory, { recursive: true });
    const output = path.join(directory, `${randomUUID()}.png`);
    const execution = await pi.exec(binary, [...prefix, 'export', design.absolute, design.frame, output, '--scale', '0.5'], { cwd: ctx.cwd, signal: owner(ctx).lifetime.signal, timeout: 120000 });
    if (execution.code !== 0 || execution.killed) throw new Error(execution.stderr || 'Preview render cancelled or timed out.');
    const bytes = await readFile(output);
    if (bytes.length > 5 * 1024 * 1024) throw new Error('Preview exceeds 5 MiB. Use MCP export with a smaller scale.');
    pi.sendMessage({
      customType: 'figlens-preview', display: true,
      content: [
        { type: 'text', text: `**${design.name}** · ${design.file}\n[Open reference image](${pathToFileURL(output).href})\n${design.instances.length ? `${design.instances.length} component instances available for optional mapping.` : 'This scope has no component instances to map. OMP can still read its layout and build it.'}` },
        { type: 'image', mimeType: 'image/png', data: bytes.toString('base64') },
      ],
    });
  }

  async function pickFrame(frames: { id: string; name: string; size?: { width: number; height: number } }[], ctx: ExtensionContext) {
    const items = frames.map(frame => ({ value: frame.id, label: frame.name,
      description: `${frame.size ? `${Math.round(frame.size.width)} × ${Math.round(frame.size.height)} · ` : ''}${frame.id}` }));
    {
      let offset = 0;
      while (true) {
        const page = items.slice(offset, offset + 6);
        const labels = page.map(item => `${item.label} · ${item.description}`);
        const choice = await ctx.ui.select(`Matching screens (${offset + 1}–${offset + page.length} of ${items.length})`,
          [...labels, ...(offset ? ['Previous page'] : []), ...(offset + 6 < items.length ? ['Next page'] : [])]);
        if (choice === 'Next page') offset += 6;
        else if (choice === 'Previous page') offset -= 6;
        else return page[labels.indexOf(choice ?? '')]?.value;
      }
    }
  }

  async function chooseFrame(file: string, node: string | undefined, ctx: ExtensionContext) {
    const flow = project(ctx);
    if (!node) {
      if (!ctx.hasUI) { await requestScope(file); return; }
      const query = await ctx.ui.input('Find a screen by name', 'For example: List views. Or ask OMP to find the screen for you.');
      if (query === undefined) return;
      if (!query.trim()) { await requestScope(file); return; }
      const { frames, truncated } = await flow.frames(file, owner(ctx).lifetime.signal, query.trim());
      if (!frames.length) { await requestScope(`${file}\nThe user described the screen as: ${query}`); return; }
      if (truncated) ctx.ui.notify('Showing the first 200 matches. Search a more specific name to reach other screens.', 'warning');
      node = await pickFrame(frames, ctx);
      if (!node) return;
    }
    const design = await flow.select(file, node, owner(ctx).lifetime.signal);
    show(`Saved selection: **${design.name}** (${design.frame})\n${design.file}\nAsk OMP to implement it. Mapping is optional; a new request can name a different file or screen.`, ctx);
    if (ctx.mode === 'tui') ctx.ui.setStatus('figlens', `figlens · ${design.frame}`);
    if (ctx.hasUI) {
      try { await preview(design, ctx); }
      catch (error) { ctx.ui.notify(`Frame selected; preview unavailable: ${(error as Error).message}`, 'warning'); }
    }
  }

  pi.on('session_switch', closeOwners);
  pi.on('session_shutdown', closeOwners);
  // Watch targets this session subscribed to or acknowledged, kept in the session branch. The figlens MCP server
  // here comes from OMP's MCP configuration, whose --root folders an extension cannot read, so a hook cannot run
  // changes with that tool's authority: OMP only reminds the agent to call changes itself.
  let targets = new Targets();
  const restore = async (_event: unknown, ctx: ExtensionContext) => { targets = restoreTargets(ctx.sessionManager.getBranch()); };
  pi.on('session_start', restore);
  pi.on('session_switch', restore);
  pi.on('session_tree', restore);
  pi.on('tool_result', async event => {
    if (targets.observe(event.toolName, event.input, event.content, event.isError)) pi.appendEntry(ENTRY, [...targets.list]);
  });
  // The reminder joins each model call without entering the session, so it leaves no copy behind.
  pi.on('context', async event => {
    const text = reminder(targets.list);
    return text ? { messages: [...event.messages, { role: 'custom', customType: 'figlens', content: text, display: false, timestamp: Date.now() }] } : undefined;
  });

  const COMMANDS = {
    open: 'Find a design from a file, screen name, purpose or visible text',
    preview: 'Start the local viewer and return its link',
    plan: 'Inspect the design and relevant code, write a plan; no edits',
    yolo: 'Plan, implement, verify and clean up the temporary plan and exports',
    frame: 'Search the saved file, or select a frame id directly',
    map: 'Propose reusable component matches for the current design',
    review: 'Accept, edit or skip pending component mappings',
    status: 'Show the manual selection and mapping states',
    close: 'Stop the viewer and clear the manual selection',
    help: 'List these commands',
  };
  pi.registerCommand('figlens', {
    description: 'Plan or implement a design, select a scope or review component mappings',
    getArgumentCompletions: prefix => Object.entries(COMMANDS)
      .filter(([value]) => value.startsWith(prefix)).map(([value, description]) => ({ value, label: value, description })),
    handler: async (args, ctx) => {
      const match = args.trimStart().match(/^(\S+)(?:\s([\s\S]*))?$/);
      const command = match?.[1];
      try {
        if (!command || command === 'help' || command === '--help') { show(HELP, ctx); return; }
        if (!Object.hasOwn(COMMANDS, command)) {
          show(`Unknown figlens command: **${command}**.\n\n${HELP}`, ctx); return;
        }
        let rest = match?.[2]?.trim() || '';
        if (command === 'preview') {
          await ctx.waitForIdle();
          const file = ((rest.startsWith('"') && rest.endsWith('"')) || (rest.startsWith("'") && rest.endsWith("'"))) ? rest.slice(1, -1) : rest;
          const absolute = path.resolve(ctx.cwd, file);
          if (file && path.extname(file).toLowerCase() === '.fig' && existsSync(absolute)) {
            const started = await owner(ctx).viewer.start(absolute, undefined, { cwd: ctx.cwd, signal: owner(ctx).lifetime.signal });
            show(`[Open design viewer](${started.url})`, ctx);
            return;
          }
          await sendRequest('preview', rest);
          return;
        }
        if (command === 'plan') {
          await ctx.waitForIdle();
          await sendRequest('plan', rest);
          return;
        }
        if (command === 'yolo') {
          await ctx.waitForIdle();
          await sendRequest('yolo', match?.[2] || '');
          return;
        }
        const frameOption = command === 'open' ? rest.match(/^([\s\S]+)\s+--frame\s+(\S+)$/) : undefined;
        if (frameOption) rest = frameOption[1].trim();
        if ((rest.startsWith('"') && rest.endsWith('"')) || (rest.startsWith("'") && rest.endsWith("'"))) rest = rest.slice(1, -1);
        await ctx.waitForIdle();
        if (command === 'open' && !frameOption) { await requestScope(rest); return; }
        const flow = project(ctx);
        if (rest && !['open', 'frame'].includes(command)) throw new Error(`/figlens ${command} takes no arguments. To implement a design, send your request as a normal message to OMP.`);
        if (command === 'open') {
          if (!rest) throw new Error('Provide a saved .fig file, for example: /figlens open ./design.fig. You can also ask OMP to build a screen directly.');
          const { file } = await flow.source(rest);
          await chooseFrame(file, frameOption?.[2], ctx);
        } else if (command === 'frame') {
          const active = (await flow.read()).state.active;
          if (!active) throw new Error('No manually saved file. Use /figlens open and describe the screen, or ask OMP directly. Known IDs are optional advanced controls in /figlens help.');
          await chooseFrame(active.file, rest || undefined, ctx);
        } else if (command === 'map') {
          await sendRequest('map', '');
        } else if (command === 'review') await reviewMappings(flow, ctx, message => show(message, ctx), owner(ctx).lifetime.signal);
        else if (command === 'status') {
          if ((await flow.read()).state.active) show(describe(await flow.bindings({}, owner(ctx).lifetime.signal)), ctx);
          else show('No manually saved selection. OMP can read a .fig directly from your request. Use /figlens review for pending mappings.', ctx);
        }
        else if (command === 'close') {
          await owner(ctx).viewer.close();
          await flow.close();
          if (ctx.mode === 'tui') ctx.ui.setStatus('figlens', undefined);
          show('Local viewer stopped and saved selection cleared. Component mappings are kept.', ctx);
        }
      } catch (error) {
        const detail = (error as Error).message;
        const hint = (error as NodeJS.ErrnoException).code === 'ENOENT'
          ? 'Check that the file exists and the path is relative to this project, or use an absolute path.'
          : 'Ask OMP to inspect the problem with the figlens MCP tools. /figlens help shows the optional manual controls.';
        show(`**Could not complete /figlens ${command}.**\n\n${detail}\n\n${hint}`, ctx);
      }
    },
  });

  pi.registerTool({
    name: 'figlens_preview', label: 'Open design viewer',
    description: 'Start the local interactive viewer for a local .fig file, optionally focused on an exact node. Returns its loopback URL; does not launch a browser or modify the application, manual selection or mappings. May write render cache. Replaces this session’s previous viewer after successful startup; viewers stop when the OMP session shuts down.',
    parameters: z.object({ file: z.string().min(1).max(4096), node: z.string().min(1).max(200).optional() }),
    approval: 'exec',
    execute: async (_id, params, signal, _update, ctx) => result(await owner(ctx).viewer.start(path.resolve(ctx.cwd, params.file), params.node, { cwd: ctx.cwd, signal: signal ? AbortSignal.any([owner(ctx).lifetime.signal, signal]) : owner(ctx).lifetime.signal })),
  });

  pi.registerTool({
    name: 'figlens_bindings', label: 'Design component mappings',
    description: 'Read a frame’s component instances and this project’s recorded mappings (approved, pending, stale or unmatched). Supply file and frame together to read that scope without changing the manual selection; omit both to use the saved selection. Returns current variant properties/text, mapped targets with import/usage examples, and nextOffset when more instances remain. Zero instances returns an empty list, not a read failure. Read-only; never approves a mapping. Recorded hashes cover listed evidence files, not correctness.',
    parameters: z.object({ ...selection, offset: z.number().int().min(0).optional(), limit: z.number().int().min(1).max(50).optional() }),
    approval: 'read',
    async execute(_id, params, signal, _onUpdate, ctx) { return result(await project(ctx, signal).bindings(params, signal)); },
  });

  pi.registerTool({
    name: 'figlens_propose_bindings', label: 'Propose component mappings',
    description: 'Record 1-20 candidate mappings from design instances to existing project implementations as pending for human review with /figlens review. Stores design identity, variant/structure and file hashes; checks are agent-reported results, not independent proof. This call cannot approve mappings. Supply file and frame together to override the saved scope for this call only.',
    parameters: z.object({ ...selection, proposals: z.array(z.object({
      instance: z.string().min(1).max(200), target: Target,
      dependencies: z.array(z.string().min(1).max(2000)).max(20).optional(),
      rationale: z.string().min(1).max(2000), checks: z.array(z.string().min(1).max(2000)).max(20).optional(),
      issues: z.array(z.string().min(1).max(2000)).max(10).optional(),
    })).min(1).max(20) }),
    approval: 'write',
    async execute(_id, params, signal, _onUpdate, ctx) {
      const flow = project(ctx, signal);
      return result(await withFileMutationQueue(flow.guide, () => flow.propose(params, signal)));
    },
  });
}

import { readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { Plugin } from '@opencode/plugin';
import { createAdapter, indexGrant } from './adapter.mjs';
import { registerReview } from './review-rpc.mjs';
import { operationRpc, reviewRpc } from './rpc.mjs';
import { WorkflowAuthorizationError } from '../pi/workflow.mjs';
import { Targets, check, checkInput, failure, notice, reminder } from '../pi/stale.mjs';

const string = maxLength => ({ type: 'string', minLength: 1, maxLength });
const selection = { file: string(4096), frame: string(200) };
// A directory add cursor is `d1.<16 hex>.` plus its last canonical path in hex: 20 + 2 * PATH_MAX (4096).
// shortcut: Windows long paths can exceed PATH_MAX; raise this if such a cursor is ever refused.
const DIR_CURSOR = 20 + 2 * 4096;
const object = (properties, required = []) => ({ type: 'object', properties, required, additionalProperties: false });
const texts = maxItems => ({ type: 'array', items: string(2000), maxItems });
const bool = { type: 'boolean' }, path = string(4096), id = string(200);
// An exact instance sublayer id has up to expand::MAX_DEPTH (256) segments of at most 23 bytes, as src/search/store.rs bounds it.
const node = string((256 + 1) * 23);
// The figlens MCP index, jobs, search, usages, diff, changes, watch, inspect and models tools, run as the same CLI commands.
const pixel = { type: 'integer', minimum: 0 };
const CLI_TOOLS = [
  ['index', 'Local workspace indexes for search, as the figlens MCP index tool. prepare registers file (or a project workspace) and with scope builds exactly that stored scope (0:0 is the whole file), returning workspaceId and the finished job; status reports sources and storage; add, remove, relocate, refresh, rebuild and clear_cache manage sources and indexes; track starts recording the changes of one scope with a baseline build and untrack stops it, keeping its history; embed runs the configured local model (figlens_models) over published scopes for semantic search, as jobs (mode_unavailable without a profile); visual renders one published scope (scope required) for image search and embeds it with a configured vision profile, as a job; reset deletes this workspace database only after the user asked for it. A directory file registers 10 files per call and returns nextCursor; pass it as cursor for the next page; the CLI path refuses gs://. Errors carry recovery steps; recreation (replaceUnavailable) needs the user\'s confirmation.',
    { action: { enum: ['prepare', 'status', 'add', 'remove', 'relocate', 'refresh', 'rebuild', 'track', 'untrack', 'embed', 'visual', 'clear_cache', 'reset'] },
      file: path, workspace: path, workspaceId: id, sourceId: id, scope: node, requestId: id, storage: path, replaceUnavailable: bool, cursor: string(DIR_CURSOR) }, ['action']],
  ['jobs', 'Status or cancellation of an index job by its jobId, as the figlens MCP jobs tool.',
    { action: { enum: ['status', 'cancel'] }, jobId: id, storage: path }, ['action', 'jobId']],
  ['search', 'Ranked text, semantic, visual or hybrid search, as the figlens MCP search tool. An image query takes an authorized local PNG (image) or stored node render (imageRef), optionally cropped. Give file for queries without an image, or workspaceId for prepared text/model/visual layers; index visual builds the image layer. Results carry exact ref.nodeId for figlens_inspect, matches and coverage; sources not ready list the index call that prepares them.',
    { file: path, workspaceId: id, sourceId: id, storage: path, query: string(2000), node, type: id,
      limit: { type: 'integer', minimum: 1, maximum: 200 }, cursor: string(4096), includeHidden: bool, includeInternal: bool,
      // An image search: one local PNG or one stored node render, optionally cropped; visual only with an image.
      image: path, imageRef: object({ sourceId: id, snapshotId: id, nodeId: node }, ['sourceId', 'snapshotId', 'nodeId']),
      crop: object({ x: pixel, y: pixel, width: pixel, height: pixel }, ['x', 'y', 'width', 'height']),
      mode: { enum: ['text', 'semantic', 'hybrid', 'visual'] } }],
  // A usages target and scope take any id an index stores, as src/search/usages.rs validates them.
  ['usages', 'Exact relations of one node or resource in one stored scope, as the figlens MCP usages tool: give file to read a .fig now, or workspaceId to read its prepared index of scope. direction in (default) lists what points at it, out what it points at, with library {kind, namespace, key} on a use of a cached library copy. Results carry exact refs, coverage and a snapshotId; a changed source is source_stale. With workspaceId, library {kind, namespace, key} (from an out result) instead of node or resource lists the layers in every visible source whose cached copy uses that library component, style or variable. Without namespace it lists only copies naming none and is never complete. Its definition stays unresolved unless library.definition {sourceId, snapshotId, nodeId}, an exact ref an earlier reply gave, selects one: then it is reported selected with keyEvidence unverified, and each use\'s definitionMatch compares its cached copy with it: equal (same fingerprint, not proof the library published it), definition_mismatch or unknown. It asks read on the definition\'s source as well as the sources it reads.',
    { file: path, workspaceId: id, sourceId: id, storage: path, node, resource: node, scope: node, relation: string(200),
      library: object({ kind: { enum: ['component', 'style', 'variable'] }, namespace: node, key: node,
        definition: object({ sourceId: id, snapshotId: id, nodeId: node }, ['sourceId', 'snapshotId', 'nodeId']) }, ['kind', 'key']),
      direction: { enum: ['in', 'out'] }, snapshotId: id, includeHidden: bool, limit: { type: 'integer', minimum: 1, maximum: 200 }, cursor: string(4096) }],
  ['diff', 'What changed between two saved revisions of a design (old, file), as the figlens MCP diff tool: layers match by exact id and type only, unknown means a side stopped or left that layer unexpanded, not removed. Page with nextCursor for the same pair and node.',
    { old: path, file: path, node, limit: { type: 'integer', minimum: 1, maximum: 500 }, cursor: string(4096) }, ['old', 'file']],
  ['changes', 'Recorded design changes of the scopes index track follows, as the figlens MCP changes tool; never writes or builds. A query subscription\'s subscriptionId pages its stored search evaluations instead, with no revision pages: evaluation current, current_for_index (the file changed since that index: refresh, then evaluate), pending, or unavailable (also when its evaluation at this publication failed, with that reason); a stored evaluation too large or damaged to page fails with a recovery that acks past it. Pages revisions oldest first after cursor, else after subscriptionId\'s or consumer\'s checkpoint, else from the oldest kept; each changes revision\'s impact summarizes the layers its changes reach (null before it was recorded); revision pages one revision\'s changed nodes, then its impact\'s listed layers, each marked by entry; limit is 1-50 revisions, or 1-500 entries with revision. tracking says when a scope needs refresh to record a change; event_gap means retention deleted unread revisions: follow its recovery.',
    { workspaceId: id, sourceId: id, scope: node, consumer: string(128), subscriptionId: id, cursor: string(4096), revision: id,
      limit: { type: 'integer', minimum: 1, maximum: 500 }, storage: path }, ['workspaceId']],
  ['watch', 'Watching tracked scopes, change consumers and subscriptions, as the figlens MCP watch tool. start holds a lease on a tracked scope (sourceId when the workspace has several) for this session: the workspace\'s shared runner refreshes it on each save, so figlens_changes shows new revisions without an index call; it asks read on every registered design (its runner also evaluates saved questions reaching other designs) and edit on the workspace. A requestId replays this session\'s live or pending start and reports its ended lease (kept 1 h, newest 1024), never restarting it; the same requestId with other arguments is refused. stop ends a lease this session started (leaseId); deleting the session or unloading the plugin ends them all and logs any release it could not confirm. status lists the workspace\'s leases and runner, read-only. ack moves a consumer\'s checkpoint (same sourceId and scope), or a subscription\'s (subscriptionId), to the nextCursor of the last figlens_changes page it handled. An older cursor normally leaves it, so a retry is safe; a cursor issued before retention deleted revisions it had not passed is event_gap and writes nothing: follow its recovery. A current recovery cursor moves a checkpoint behind such a deletion back to it, so the kept revisions replay; advanced is true only for forward progress, and the returned checkpoint is the one held. subscribe follows a source, scope or exact node (never a same-name layer: target_missing or identity_uncertain) from now, with its own checkpoint; owner makes it temporary for that task. subscribe with query (and type) saves a search of one source\'s scope instead and stores its top-50 evaluation, and evaluate (no sourceId: it evaluates the subscription\'s own source) stores a newer one after a publication, and a watch lease on that scope makes its runner store it unasked (unavailable evaluation_too_large past 128 KiB), and figlens_changes only reads them; delta refs, rankChanged\'s too (with from and to), are exact sourceId/snapshotId/nodeId, rankChanged is null when rankComparable is false, and nodes compare by sourceId, which relocate keeps. sources (visible, resolved now, or comma-separated sourceIds, at most 10) instead of sourceId saves the search, or a library question (library {kind, namespace, key, definition}; read is also asked on the definition\'s source), over that fixed set: causes name members with new bytes in delta.changedSourceIds, a library question lists its uses\' definitionMatch and never follows transitive dependencies (coverage.transitive not_followed; delta.notFollowedSourceIds names changed members holding no use), a caller who cannot see every member reads it as unknown, and removing a member disables it (disabled.reason source_removed; a damaged set reads sources_unreadable: unsubscribe, then subscribe again). list shows visible subscriptions; unsubscribe removes one (or an owner\'s temporary ones) and forget a consumer\'s raw checkpoints; neither untracks.',
    { action: { enum: ['start', 'stop', 'status', 'ack', 'subscribe', 'evaluate', 'list', 'unsubscribe', 'forget'] }, workspaceId: id, consumer: string(128), cursor: string(4096),
      sourceId: id, scope: node, subscriptionId: id, node, query: string(2000), type: id, sources: string(4096),
      library: object({ kind: { enum: ['component', 'style', 'variable'] }, namespace: node, key: node,
        definition: object({ sourceId: id, snapshotId: id, nodeId: node }, ['sourceId', 'snapshotId', 'nodeId']) }, ['kind', 'key']),
      owner: string(128), after: id, leaseId: id, requestId: id, storage: path },
    ['action', 'workspaceId']],
  ['models', 'Local model profiles, as the figlens MCP models tool: bge-m3 (text) for semantic and hybrid search, and siglip-base (image) for the vision layer of visual search. list shows the documented profiles with model, revision, license and the files each needs; status reports each configured profile ready or unavailable with the reason, or the setup steps when none is configured; configure checks a model directory the user already downloaded against pinned SHA-256 digests, starts the figlens-embed shipped beside figlens once offline and records the profile; remove forgets the profile and keeps its files. Nothing is downloaded and no design text or image leaves the machine. configure asks read on modelDir and each pinned file it names; configure and remove ask edit on the figlens config root that records profiles.',
    { action: { enum: ['list', 'status', 'configure', 'remove'] }, profile: id, modelDir: path }, ['action']],
  ['inspect', 'Compact expanded node summary of a .fig node or exact instance sublayer, as the figlens MCP inspect tool.',
    { file: path, node, depth: { type: 'integer', minimum: 0, maximum: 10 }, images: bool, states: bool, flat: bool, fullText: bool, colors: bool, compareVariant: node, compare: node }, ['file', 'node']],
];
const result = data => {
  const text = JSON.stringify(data, null, 2);
  if (Buffer.byteLength(text) > 4 * 1024 * 1024) throw new Error('Result exceeds 4 MiB. Request a smaller page.');
  // OpenCode refuses a structured output from a tool that declares no output schema.
  return { content: [{ type: 'text', text }], metadata: { figlens: true } };
};

export default Plugin.define({ id: 'figlens', async setup(ctx) {
  const adapter = createAdapter(ctx, import.meta.url);
  const registrations = [];
  registrations.push(await ctx.mcp.transform(adapter.configureMcp));
  const skillPath = fileURLToPath(new URL('../skills/figlens/SKILL.md', import.meta.url));
  const skill = await readFile(skillPath, 'utf8');
  registrations.push(await ctx.skill.transform(editor => {
    if (!editor.list().some(item => item.name === 'figlens')) editor.add({
      id: 'figlens', name: 'figlens', description: 'Read local Figma designs, plan and implement screens, and review reusable mappings.',
      path: skillPath, content: skill,
    });
  }));
  registrations.push(await registerReview(ctx, adapter));
  const operations = await ctx.rpc.register(operationRpc, { run: async (input, call) => {
    try { return await adapter.operation(input, call.signal); }
    catch (failure) {
      const error = failure instanceof WorkflowAuthorizationError ? failure.cause : failure;
      if (call.signal.aborted || error?.name === 'AbortError' || error?._tag === 'Permission.DeclinedError') return call.error('cancelled', 'Operation cancelled; reload the stored state before retrying.', null);
      if (error?._tag === 'Tool.Error') return call.error('permission_denied', error.message, null);
      return call.error('storage_error', error?.message ?? String(error), null);
    }
  } });
  registrations.push(operations);
  registrations.push(await ctx.command.transform(editor => editor.add({ name: 'figlens',
    description: 'Plan or implement a design, select a scope or review component mappings: open, preview, plan, yolo, frame, map, review, status, close, help', execute: async input => {
      const text = input.prompt.text.trim();
      if (text === 'review' || text === 'frame') {
        await adapter.scope(input.sessionID);
        await ctx.session.wait({ sessionID: input.sessionID });
        await operations.events.emit('manual', { sessionID: input.sessionID, action: text });
        await ctx.session.synthetic({ sessionID: input.sessionID, resume: false,
          text: `figlens ${text}: use the active native TUI dialog. Noninteractive clients leave mappings and selection unchanged.` });
      } else await adapter.commandHandler(input);
    },
  })));
  registrations.push(await ctx.tool.transform(editor => {
    editor.add({ name: 'figlens_preview', description: 'Start a local interactive viewer for a .fig file and optional node. Returns the server loopback URL; may write render cache. Preserves the old viewer on failure. Never changes selection or mappings.',
      input: object({ file: string(4096), node: string(200) }, ['file']),
      options: { codemode: false },
      execute: async ({ file, node }, call) => result(await adapter.preview(await adapter.scope(call.sessionID, call.signal), file, node)),
    });
    editor.add({ name: 'figlens_bindings', description: 'Read component mappings, evidence and current variants. Supply file and frame together for a temporary override; omit both for the manual selection. Read-only, never approves. Paginate using nextOffset.',
      input: object({ ...selection, offset: { type: 'integer', minimum: 0 }, limit: { type: 'integer', minimum: 1, maximum: 50 } }),
      options: { codemode: false },
      execute: async (input, call) => {
        const current = await adapter.scope(call.sessionID, call.signal);
        return result(await current.flow.bindings(input, current.signal));
      },
    });
    editor.add({ name: 'figlens_propose_bindings', description: 'Record 1–20 reusable component mappings as pending for /figlens review. No approval tool exists. Supply file and frame together for this call only. Checks are agent-reported; human approval and compilation remain separate.',
      input: object({ ...selection, proposals: { type: 'array', minItems: 1, maxItems: 20, items: object({
        instance: string(200), target: reviewRpc.methods.review.input.properties.target,
        dependencies: texts(20), rationale: string(2000), checks: texts(20), issues: texts(10),
      }, ['instance', 'target', 'rationale']) } }, ['proposals']),
      options: { codemode: false },
      execute: async (input, call) => {
        const current = await adapter.scope(call.sessionID, call.signal);
        return result(await current.flow.propose(input, current.signal));
      },
    });
    // An MCP server already serves these tools unless the user's figlens server is disabled or dropped.
    if (!adapter.cliPath) return;
    for (const [name, description, properties, need] of CLI_TOOLS) editor.add({ name: `figlens_${name}`, description,
      input: object(properties, need), options: { codemode: false },
      execute: async (input, call) => result(await adapter.cli(await adapter.scope(call.sessionID, call.signal), name, input)),
    });
  }));
  // Reset and recreation through the MCP index tool ask the same host permission as the CLI path.
  registrations.push(await ctx.tool.hook('execute.before', async call => {
    // On the CLI path figlens_index asks inside adapter.cli; a server named figlens would match it here too.
    const grant = !adapter.cliPath && call.tool === `${adapter.mcpName}_index` && indexGrant(call.input ?? {});
    if (grant) await (await adapter.scope(call.sessionID)).authorize('figlens_index', [grant]);
  }));
  // Watch targets each session subscribed to or acknowledged, held in memory: after an OpenCode restart a session
  // is checked again from its next subscribe or ack. On the CLI path the check is adapter.cli's changes, asking the
  // same read and bash permissions as the agent's own call; an MCP server's --root folders are not visible here,
  // so through MCP the session is only reminded to call changes itself.
  const watched = new Map(), notes = new Map();
  registrations.push(await ctx.tool.hook('execute.after', call => {
    const targets = watched.get(call.sessionID) ?? new Targets();
    if (targets.observe(call.tool, call.input, call.result?.content, call.status !== 'completed')) watched.set(call.sessionID, targets);
  }));
  registrations.push(await ctx.session.hook('prompt', async input => {
    notes.delete(input.sessionID);
    const targets = watched.get(input.sessionID);
    if (!targets?.list.length) return;
    let text = reminder(targets.list);
    if (adapter.cliPath) {
      // One check at a time, so at most one read permission question is open while the deadline runs; each
      // scope carries the batch signal, so the deadline also stops its CLI child.
      text = notice(await check(targets.turn(), async (target, signal) => {
        try { return await adapter.cli(await adapter.scope(input.sessionID, signal), 'changes', checkInput(target)); }
        catch (error) { throw error.cause?.stderr ? failure(error.cause.stderr) : error; }
      }, adapter.signal, { parallel: 1 }), targets.dropped);
    }
    if (text) notes.set(input.sessionID, text);
  }));
  // The note stays in each model call of that prompt's turn; the next prompt checks again.
  registrations.push(await ctx.session.hook('context', input => {
    const text = notes.get(input.sessionID);
    if (text) input.system.push({ type: 'text', text });
  }));
  const events = (async () => {
    try {
      for await (const event of ctx.event.subscribe({ types: ['session.deleted'], signal: adapter.signal })) {
        watched.delete(event.data.sessionID);
        notes.delete(event.data.sessionID);
        await adapter.close(event.data.sessionID);
      }
    } catch (error) {
      if (!adapter.signal.aborted) { console.error('figlens session cleanup stream failed:', error); await adapter.dispose(); }
    }
  })();
  return async () => {
    try { await adapter.dispose(); }
    finally {
      await events;
      for (const registration of registrations.reverse()) await registration.dispose();
    }
  };
} });

import { mkdir, readFile } from 'node:fs/promises';
import { randomUUID } from 'node:crypto';
import { existsSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { Type } from 'typebox';
import { getMarkdownTheme, withFileMutationQueue, type ExtensionAPI, type ExtensionContext } from '@earendil-works/pi-coding-agent';
import { Container, Image, Input, Markdown, SelectList, fuzzyFilter, truncateToWidth } from '@earendil-works/pi-tui';
import { Workflow } from './workflow.mjs';
import { Viewer } from './viewer.mjs';
import { buildRequest } from './requests.mjs';
import { ENTRY, Targets, bounded, changesArgs, check, failure, notice, reader, restore as restoreTargets } from './stale.mjs';

const HELP = [
  "## figlens",
  "",
  "Ask Pi directly: **\"Build the List views screen from ./design.fig using this project's components.\"**",
  "Pi can find and read the design through MCP. No open command or node ID is needed.",
  "Asking Pi to find copy or a screen searches the .fig directly and stores nothing. For repeated searches, ask it to enable an index for a design and scope: it prepares a local index once (no setup command), reports the job until ready, then reuses it across restarts and hosts. Resetting that index needs your explicit request. Asking where a component, variable, style or image is used lists its exact usages the same way: from the .fig directly, or from that index once enabled. Across every design with an index, it also lists where a library component, style or variable is used, by the library reference that outgoing usages on a layer names. Asking it to follow the changes of a design tracks a scope of that index and lists what changed since the last change it handled; asking it to watch that scope picks up each save while its figlens server runs. Searching by meaning or across languages needs an optional local model that you download yourself; ask Pi to list and set it up with the figlens models tool (nothing is downloaded and no design text leaves the machine), and without one search stays text. Giving it a screenshot, or pointing at a found screen, and asking for screens that look like it searches that index by image once its visual layers are built (experimental; the image is not stored).",
  "",
  "Optional shortcuts:",
  "- `/figlens open [description]` — tell Pi what you know: a file, screen name, purpose or visible text. Pi finds it or asks a recognizable follow-up.",
  "- `/figlens preview [description]` — start the local interactive viewer for a design; Pi resolves names and returns its link.",
  "- `/figlens plan [request]` — plan only the requested region or pages before implementing.",
  "- `/figlens yolo [request]` — plan, implement and verify the requested scope, then clean up only this run's temporary plan, scratch exports and processes after success; e.g. `/figlens yolo Home Screen from ./app.fig in ./web`.",
  "",
  "Advanced: saved selections and reusable component matches (not required to build):",
  "- `/figlens open \"./design files/mobile.fig\" --frame 12:345` — use a known node.",
  "- `/figlens frame` — search within the saved file; add an ID to select it directly.",
  "- `/figlens status` — inspect the saved selection.",
  "- `/figlens map` — propose reusable component matches for the design in this conversation.",
  "- `/figlens review` — review pending proposals across this project; no open required.",
  "- `/figlens close` — stop the viewer and clear the saved selection, keeping reviewed mappings.",
  "",
  "Mappings are optional. Pi can implement the screen immediately.",
].join('\n');
const selection = {
  file: Type.Optional(Type.String({ description: 'Local .fig path. Supply file and frame together to override the saved selection for this call.' })),
  frame: Type.Optional(Type.String({ description: 'Frame id in that file.' })),
};
const Target = Type.Object({
  path: Type.String({ minLength: 1, maxLength: 4096, description: 'Existing implementation file, relative to the project root.' }),
  export: Type.String({ minLength: 1, maxLength: 200, description: 'Actual export name, default, or none for plain HTML.' }),
  import: Type.String({ minLength: 1, maxLength: 8000, description: 'Import statement valid at the intended implementation location; for plain HTML, describe which existing block to reuse.' }),
  example: Type.String({ minLength: 1, maxLength: 8000, description: 'Framework-native usage, including props/slots and dynamic text handling.' }),
});
function result(data: unknown) {
  const text = JSON.stringify(data, null, 2);
  return { content: [{ type: 'text' as const, text }], structuredContent: JSON.parse(text), details: data };
}

function describe(data: Awaited<ReturnType<Workflow['bindings']>>) {
  const priority = (item: typeof data.items[number]) => item.status === 'approved' ? 0 : ('issues' in item && (item.issues.length || item.needsReview.length)) ? 1 : item.status === 'unmatched' ? 3 : 2;
  const listed = [...data.items].sort((a, b) => priority(a) - priority(b)).slice(0, 8);
  const rows = listed.map(item => {
    const target = 'approved' in item ? item.approved[0]?.target.path : undefined;
    const issue = 'issues' in item && item.issues.length ? ' · text needs review' : 'needsReview' in item && item.needsReview.length ? ' · new variant/structure' : '';
    return `- **${item.status}** · ${item.name} (${item.id})${target ? ` → ${target}` : ''}${issue}`;
  });
  const approved = data.items.filter(item => 'approved' in item && item.status === 'approved').slice(0, 3);
  const examples = approved.flatMap(item => 'approved' in item ? [
    `**Reuse: ${item.name}**`, '```', item.approved[0].target.import, item.approved[0].target.example, '```',
  ] : []);
  return [`**${data.name}** · ${data.frame}`, `${data.file} · loaded ${data.items.length} of ${data.total} instances`, '', ...rows,
    ...(data.items.length > listed.length ? [`${data.items.length - listed.length} more loaded instances available through figlens_bindings.`] : []), ...examples,
    ...(data.nextOffset !== null ? [`More instances: call figlens_bindings with offset=${data.nextOffset}.`] : []),
    '', 'Mappings: .figlens/component-mappings.md', 'Mappings are optional. Ask Pi to implement the screen, or /figlens review to decide pending proposals.',
  ].join('\n');
}

export default function figlens(pi: ExtensionAPI) {
  const wrapper = fileURLToPath(new URL('../bin/figlens.js', import.meta.url));
  const bundled = !process.env.FIGLENS_BIN && existsSync(wrapper);
  const binary = process.env.FIGLENS_BIN || (bundled ? process.execPath : 'figlens');
  const prefix = bundled ? [wrapper] : [];
  const viewer = new Viewer(binary, prefix);
  pi.registerMessageRenderer('figlens', message => new Markdown(
    typeof message.content === 'string' ? message.content : JSON.stringify(message.content), 1, 1, getMarkdownTheme(),
  ));
  pi.registerMessageRenderer('figlens-preview', message => {
    const container = new Container();
    for (const part of typeof message.content === 'string' ? [{ type: 'text' as const, text: message.content }] : message.content) {
      if (part.type === 'text') container.addChild(new Markdown(part.text, 1, 0, getMarkdownTheme()));
      else if (part.type === 'image') container.addChild(new Image(part.data, part.mimeType,
        { fallbackColor: text => text }, { maxWidthCells: 80, maxHeightCells: 24 }));
    }
    return container;
  });
  let workflow: Workflow | undefined;
  function project(ctx: ExtensionContext) {
    if (!workflow || workflow.root !== path.resolve(ctx.cwd)) {
      workflow = new Workflow(ctx.cwd, async (args: string[], signal?: AbortSignal) => {
        const execution = await pi.exec(binary, [...prefix, ...args], { cwd: ctx.cwd, signal, timeout: 120000 });
        if (execution.code !== 0 || execution.killed) {
          throw new Error(`Could not ${args[0]} the design: ${execution.stderr.trim().slice(0, 2000) || 'cancelled or timed out'}`);
        }
        try { return JSON.parse(execution.stdout); }
        catch { throw new Error('figlens returned invalid JSON. Check the installed binary and frame id.'); }
      });
    }
    return workflow;
  }

  function show(data: unknown, ctx: ExtensionContext) {
    pi.sendMessage({ customType: 'figlens', content: typeof data === 'string' ? data : JSON.stringify(data, null, 2), display: true });
  }

  async function requestScope(request: string) {
    pi.sendUserMessage(await buildRequest('open', request, import.meta.url));
  }

  async function preview(design: Awaited<ReturnType<Workflow['design']>>, ctx: ExtensionContext) {
    const directory = await project(ctx).referenceDirectory();
    await mkdir(directory, { recursive: true });
    const output = path.join(directory, `${randomUUID()}.png`);
    const execution = await pi.exec(binary, [...prefix, 'export', design.absolute, design.frame, output, '--scale', '0.5'], { cwd: ctx.cwd, signal: ctx.signal, timeout: 120000 });
    if (execution.code !== 0 || execution.killed) throw new Error(execution.stderr || 'Preview render cancelled or timed out.');
    const bytes = await readFile(output);
    if (bytes.length > 5 * 1024 * 1024) throw new Error('Preview exceeds 5 MiB. Use MCP export with a smaller scale.');
    pi.sendMessage({
      customType: 'figlens-preview', display: true,
      content: [
        { type: 'text', text: `**${design.name}** · ${design.file}\n[Open reference image](${pathToFileURL(output).href})\n${design.instances.length ? `${design.instances.length} component instances available for optional mapping.` : 'This scope has no component instances to map. Pi can still read its layout and build it.'}` },
        { type: 'image', mimeType: 'image/png', data: bytes.toString('base64') },
      ],
    });
  }

  async function pickFrame(frames: { id: string; name: string; size?: { width: number; height: number } }[], ctx: ExtensionContext) {
    const items = frames.map(frame => ({ value: frame.id, label: frame.name,
      description: `${frame.size ? `${Math.round(frame.size.width)} × ${Math.round(frame.size.height)} · ` : ''}${frame.id}` }));
    if (ctx.mode !== 'tui') {
      let offset = 0;
      while (true) {
        const page = items.slice(offset, offset + 6);
        const labels = page.map(item => `${item.label} · ${item.description}`);
        const choice = await ctx.ui.select(`Matching screens (${offset + 1}–${offset + page.length} of ${items.length})`,
          [...labels, ...(offset ? ['Previous page'] : []), ...(offset + 6 < items.length ? ['Next page'] : [])]);
        if (choice === 'Next page') offset += 6;
        else if (choice === 'Previous page') offset -= 6;
        else return page[labels.indexOf(choice ?? '')]?.value;
      }
    }
    return ctx.ui.custom<string | undefined>((tui, theme, kb, done) => {
      const input = new Input();
      input.focused = true;
      let filtered = items;
      let list: SelectList;
      let rows = 0;
      const rebuild = () => {
        const selected = list?.getSelectedItem()?.value;
        rows = Math.max(1, Math.min(10, tui.terminal.rows - 9));
        list = new SelectList(filtered, rows, {
          selectedPrefix: text => theme.fg('accent', text), selectedText: text => theme.fg('accent', text),
          description: text => theme.fg('muted', text), scrollInfo: text => theme.fg('dim', text), noMatch: text => theme.fg('warning', text),
        });
        list.setSelectedIndex(Math.max(0, filtered.findIndex(item => item.value === selected)));
        list.onSelect = item => done(item.value);
        list.onCancel = () => done(undefined);
      };
      rebuild();
      return {
        render(width) {
          if (rows !== Math.max(1, Math.min(10, tui.terminal.rows - 9))) rebuild();
          return [truncateToWidth(theme.fg('accent', 'Select a screen · type to filter'), width), ...input.render(width),
            ...list.render(width), truncateToWidth('↑↓ / wheel: navigate · Enter: select · Esc: cancel', width)];
        },
        handleInput(data) {
          if (['tui.select.up', 'tui.select.down', 'tui.select.confirm', 'tui.select.cancel'].some(key => kb.matches(data, key as Parameters<typeof kb.matches>[1]))) list.handleInput(data);
          else {
            input.handleInput(data);
            filtered = fuzzyFilter(items, input.getValue(), item => `${item.label} ${item.description}`);
            rebuild();
          }
          tui.requestRender();
        },
        handleMouse(event) { return list.handleMouse({ ...event, y: event.y - 2 }); },
        invalidate() { input.invalidate(); list.invalidate(); },
      };
    });
  }

  async function chooseFrame(file: string, node: string | undefined, ctx: ExtensionContext) {
    const flow = project(ctx);
    if (!node) {
      if (!ctx.hasUI) { await requestScope(file); return; }
      const query = await ctx.ui.input('Find a screen by name', 'For example: List views. Or ask Pi to find the screen for you.');
      if (query === undefined) return;
      if (!query.trim()) { await requestScope(file); return; }
      const { frames, truncated } = await flow.frames(file, ctx.signal, query.trim());
      if (!frames.length) { await requestScope(`${file}\nThe user described the screen as: ${query}`); return; }
      if (truncated) ctx.ui.notify('Showing the first 200 matches. Search a more specific name to reach other screens.', 'warning');
      node = await pickFrame(frames, ctx);
      if (!node) return;
    }
    const design = await flow.select(file, node, ctx.signal);
    show(`Saved selection: **${design.name}** (${design.frame})\n${design.file}\nAsk Pi to implement it. Mapping is optional; a new request can name a different file or screen.`, ctx);
    if (ctx.mode === 'tui') ctx.ui.setStatus('figlens', `figlens · ${design.frame}`);
    if (ctx.hasUI) {
      try { await preview(design, ctx); }
      catch (error) { ctx.ui.notify(`Frame selected; preview unavailable: ${(error as Error).message}`, 'warning'); }
    }
  }

  async function review(ctx: ExtensionContext) {
    const flow = project(ctx);
    const pending = await flow.pending();
    if (!pending.length) { show('No pending component mappings in this project. Ask Pi to implement your screen, or to propose mappings if you want reusable decisions.', ctx); return; }
    if (!ctx.hasUI) { show(`${pending.length} pending mapping(s). Review requires interactive Pi or an RPC client supporting dialogs. Proposals remain pending.`, ctx); return; }
    for (const entry of pending) {
      const summary = [
        `${entry.source.name} (${entry.source.instance}) → ${entry.target.path}`,
        `Design: ${entry.source.file} · frame ${entry.source.frame}`,
        `Export: ${entry.target.export}`, entry.target.import, entry.target.example,
        `Rationale: ${entry.rationale}`,
        `Agent-reported checks (not independently verified): ${entry.checks.join('; ') || 'none'}`,
        ...entry.issues.map((issue: string) => `Needs review: ${issue}`),
      ].join('\n\n');
      show(summary, ctx);
      const action = await ctx.ui.select('Review this component mapping', ['Accept', 'Edit', 'Skip', 'Stop']);
      if (!action || action === 'Stop') break;
      if (action === 'Skip') { await flow.review(entry.id, 'skip'); continue; }
      let target = entry.target;
      if (action === 'Edit') {
        if (ctx.mode === 'tui') {
          const edited = await ctx.ui.editor('Edit target JSON (path, export, import, example)', JSON.stringify(target, null, 2));
          if (edited === undefined) continue;
          target = JSON.parse(edited);
        } else {
          const edited: Record<string, string> = {};
          for (const key of ['path', 'export', 'import', 'example'] as const) {
            const value = await ctx.ui.input(`${key} (leave empty to keep): ${target[key]}`);
            if (value === undefined) break;
            edited[key] = value || target[key];
          }
          if (Object.keys(edited).length !== 4) continue;
          target = edited;
        }
      }
      let resolution: string | undefined;
      if (entry.issues.length) {
        resolution = await ctx.ui.input('Resolve the listed issues: describe the accepted interpretation');
        if (!resolution?.trim()) continue;
      }
      if (action === 'Edit') show(`Edited target:\n\n${JSON.stringify(target, null, 2)}`, ctx);
      if (resolution) show(`Conflict resolution:\n\n${resolution}`, ctx);
      if (!await ctx.ui.confirm('Approve the mapping shown above?', `${entry.source.name} → ${target.path}\n\nApproval records your mapping decision; compilation and visual checks remain separate.`)) continue;
      await flow.review(entry.id, 'approve', { ...(action === 'Edit' ? { target } : {}), resolution }, ctx.signal);
    }
    show(`Review finished. ${(await flow.pending()).length} proposal(s) remain pending. Approved mappings are available to Pi for their matching file and frame.`, ctx);
  }

  pi.on('session_start', async (_event, ctx) => {
    pi.registerMcpServer('figlens', { command: binary, args: [...prefix, 'mcp'], cwd: ctx.cwd, exposure: 'direct' });
    const active = (await project(ctx).read()).state.active;
    if (active && ctx.mode === 'tui') ctx.ui.setStatus('figlens', `figlens · ${active.frame}`);
  });
  // Watch targets this session subscribed to or acknowledged, kept in the session branch so a resumed session
  // checks them again. The check runs the same binary as the figlens MCP server registered above, which has no
  // --root, so it reads with that tool's authority; it never acks, builds or starts a watch.
  let targets = new Targets();
  let note: string | undefined;
  let checks = new AbortController();
  // Readers still running; a shutdown or session change waits for them to exit (each is bounded).
  const reading = new Set<Promise<unknown>>();
  const stopChecks = async () => { checks.abort(); await Promise.allSettled([...reading]); };
  pi.on('session_shutdown', async () => { await stopChecks(); await viewer.close(); });
  const restore = async (_event: unknown, ctx: ExtensionContext) => {
    await stopChecks();
    checks = new AbortController();
    targets = restoreTargets(ctx.sessionManager.getBranch());
    note = undefined;
    if (ctx.mode === 'tui') ctx.ui.setStatus('figlens-changes', undefined);
  };
  pi.on('session_start', restore);
  pi.on('session_tree', restore);
  pi.on('tool_result', async event => {
    if (targets.observe(event.toolName, event.input, event.content, event.isError)) pi.appendEntry(ENTRY, [...targets.list]);
  });
  // Each user prompt checks again; programmatic runs keep the last note.
  pi.on('before_agent_start', async (event, ctx) => {
    if (event.messageType === 'custom') return;
    note = targets.list.length ? notice(await check(targets.turn(), async (target, signal) => {
      // pi.exec buffers a whole reply, so the check reads through a byte-bounded child of the native binary instead.
      const [command, ...first] = reader();
      const run = bounded(command, [...first, ...changesArgs(target)], { cwd: ctx.cwd, signal });
      reading.add(run);
      run.then(() => reading.delete(run), () => reading.delete(run));
      const execution = await run;
      if (execution.code !== 0) throw failure(execution.stderr);
      return JSON.parse(execution.stdout);
    }, AbortSignal.any([checks.signal, ...(ctx.signal ? [ctx.signal] : [])])), targets.dropped) : undefined;
    if (ctx.mode === 'tui') ctx.ui.setStatus('figlens-changes', note ? 'figlens · design context may be stale' : undefined);
  });
  // The note joins each model call of this run without entering the session, so a processed or revoked
  // target leaves no copy behind, compaction cannot drop it, and the next prompt replaces it.
  pi.on('context', async event => note
    ? { messages: [...event.messages, { role: 'custom', customType: 'figlens', content: note, display: false, timestamp: Date.now() }] }
    : undefined);

  const COMMANDS = {
    open: 'Find a design from a file, screen name, purpose or visible text',
    preview: 'Start the local viewer and return its link',
    plan: 'Inspect the design and relevant code, write a plan; no edits',
    yolo: 'Plan, implement, verify and clean up the temporary plan and exports',
    frame: 'Search the saved file, or select a frame id directly',
    map: 'Propose reusable component matches for the current design',
    review: 'Accept, edit or skip pending component mappings',
    status: 'Show the manual selection and mapping states',
    close: 'Stop the viewer and clear the manual selection',
    help: 'List these commands',
  };
  pi.registerCommand('figlens', {
    description: 'Plan or implement a design, select a scope or review component mappings',
    getArgumentCompletions: prefix => Object.entries(COMMANDS)
      .filter(([value]) => value.startsWith(prefix)).map(([value, description]) => ({ value, label: value, description })),
    handler: async (args, ctx) => {
      const match = args.trimStart().match(/^(\S+)(?:\s([\s\S]*))?$/);
      const command = match?.[1];
      try {
        if (!command || command === 'help' || command === '--help') { show(HELP, ctx); return; }
        if (!Object.hasOwn(COMMANDS, command)) {
          show(`Unknown figlens command: **${command}**.\n\n${HELP}`, ctx); return;
        }
        let rest = match?.[2]?.trim() || '';
        if (command === 'preview') {
          await ctx.waitForIdle();
          const file = ((rest.startsWith('"') && rest.endsWith('"')) || (rest.startsWith("'") && rest.endsWith("'"))) ? rest.slice(1, -1) : rest;
          const absolute = path.resolve(ctx.cwd, file);
          if (file && path.extname(file).toLowerCase() === '.fig' && existsSync(absolute)) {
            const started = await viewer.start(absolute, undefined, { cwd: ctx.cwd, signal: ctx.signal });
            show(`[Open design viewer](${started.url})`, ctx);
            return;
          }
          pi.sendUserMessage(await buildRequest('preview', rest, import.meta.url));
          return;
        }
        if (command === 'plan') {
          await ctx.waitForIdle();
          pi.sendUserMessage(await buildRequest('plan', rest, import.meta.url));
          return;
        }
        if (command === 'yolo') {
          await ctx.waitForIdle();
          pi.sendUserMessage(await buildRequest('yolo', match?.[2] || '', import.meta.url));
          return;
        }
        const frameOption = command === 'open' ? rest.match(/^([\s\S]+)\s+--frame\s+(\S+)$/) : undefined;
        if (frameOption) rest = frameOption[1].trim();
        if ((rest.startsWith('"') && rest.endsWith('"')) || (rest.startsWith("'") && rest.endsWith("'"))) rest = rest.slice(1, -1);
        await ctx.waitForIdle();
        if (command === 'open' && !frameOption) { await requestScope(rest); return; }
        const flow = project(ctx);
        if (rest && !['open', 'frame'].includes(command)) throw new Error(`/figlens ${command} takes no arguments. To implement a design, send your request as a normal message to Pi.`);
        if (command === 'open') {
          if (!rest) throw new Error('Provide a saved .fig file, for example: /figlens open ./design.fig. You can also ask Pi to build a screen directly.');
          const { file } = await flow.source(rest);
          await chooseFrame(file, frameOption?.[2], ctx);
        } else if (command === 'frame') {
          const active = (await flow.read()).state.active;
          if (!active) throw new Error('No manually saved file. Use /figlens open and describe the screen, or ask Pi directly. Known IDs are optional advanced controls in /figlens help.');
          await chooseFrame(active.file, rest || undefined, ctx);
        } else if (command === 'map') {
          pi.sendUserMessage(await buildRequest('map', '', import.meta.url));
        } else if (command === 'review') await review(ctx);
        else if (command === 'status') {
          if ((await flow.read()).state.active) show(describe(await flow.bindings({}, ctx.signal)), ctx);
          else show('No manually saved selection. Pi can read a .fig directly from your request. Use /figlens review for pending mappings.', ctx);
        }
        else if (command === 'close') {
          await viewer.close();
          await flow.close();
          if (ctx.mode === 'tui') ctx.ui.setStatus('figlens', undefined);
          show('Local viewer stopped and saved selection cleared. Component mappings are kept.', ctx);
        }
      } catch (error) {
        const detail = (error as Error).message;
        const hint = (error as NodeJS.ErrnoException).code === 'ENOENT'
          ? 'Check that the file exists and the path is relative to this project, or use an absolute path.'
          : 'Ask Pi to inspect the problem with the figlens MCP tools. /figlens help shows the optional manual controls.';
        show(`**Could not complete /figlens ${command}.**\n\n${detail}\n\n${hint}`, ctx);
      }
    },
  });

  pi.registerTool({
    name: 'figlens_preview', label: 'Open design viewer',
    description: 'Start the local interactive viewer for a local .fig file, optionally focused on an exact node. Returns its loopback URL; does not launch a browser or modify the application, manual selection or mappings. May write render cache. Replaces this session’s previous viewer after successful startup; viewers stop when the Pi session shuts down.',
    parameters: Type.Object({
      file: Type.String({ minLength: 1, description: 'Local .fig path resolved from the current request.' }),
      node: Type.Optional(Type.String({ minLength: 1, description: 'Exact node ID to focus; omit to browse the whole file.' })),
    }),
    outputSchema: Type.Object({}, { additionalProperties: true }),
    annotations: { readOnlyHint: false, destructiveHint: false, openWorldHint: false },
    executionMode: 'sequential',
    execute: async (_id, params, signal, _update, ctx) => result(await viewer.start(path.resolve(ctx.cwd, params.file), params.node, { cwd: ctx.cwd, signal })),
  });

  pi.registerTool({
    name: 'figlens_bindings', label: 'Design component mappings',
    description: 'Read a frame’s component instances and this project’s recorded mappings (approved, pending, stale or unmatched). Supply file and frame together to read that scope without changing the manual selection; omit both to use the saved selection. Returns current variant properties/text, mapped targets with import/usage examples, and nextOffset when more instances remain. Zero instances returns an empty list, not a read failure. Read-only; never approves a mapping. Recorded hashes cover listed evidence files, not correctness.',
    parameters: Type.Object({
      ...selection,
      offset: Type.Optional(Type.Integer({ minimum: 0, description: 'First instance index, default 0; pass nextOffset from the previous result.' })),
      limit: Type.Optional(Type.Integer({ minimum: 1, maximum: 50, description: 'Instances per page, 1-50, default 20.' })),
    }),
    outputSchema: Type.Object({}, { additionalProperties: true }),
    annotations: { readOnlyHint: true, destructiveHint: false, openWorldHint: false },
    executionMode: 'sequential',
    async execute(_id, params, signal, _onUpdate, ctx) { return result(await project(ctx).bindings(params, signal)); },
  });

  pi.registerTool({
    name: 'figlens_propose_bindings', label: 'Propose component mappings',
    description: 'Record 1-20 candidate mappings from design instances to existing project implementations as pending for human review with /figlens review. Stores design identity, variant/structure and file hashes; checks are agent-reported results, not independent proof. This call cannot approve mappings. Supply file and frame together to override the saved scope for this call only.',
    parameters: Type.Object({
      ...selection,
      proposals: Type.Array(Type.Object({
        instance: Type.String({ minLength: 1, maxLength: 200, description: 'Instance ID in this frame, as returned by figlens_bindings.' }), target: Target,
        dependencies: Type.Optional(Type.Array(Type.String({ minLength: 1, maxLength: 2000 }), { maxItems: 20, description: 'Supporting project files, relative to the project root; their hashes are recorded with the target file.' })),
        rationale: Type.String({ minLength: 1, maxLength: 2000, description: 'Why the actual implementation and its usage match this instance.' }),
        checks: Type.Optional(Type.Array(Type.String({ minLength: 1, maxLength: 2000 }), { maxItems: 20, description: 'Checks actually executed for this mapping, each with its result; omit checks not run.' })),
        issues: Type.Optional(Type.Array(Type.String({ minLength: 1, maxLength: 2000 }), { maxItems: 10, description: 'Unresolved conflicts for review, such as design text the implementation does not expose.' })),
      }), { minItems: 1, maxItems: 20 }),
    }),
    outputSchema: Type.Object({}, { additionalProperties: true }),
    annotations: { readOnlyHint: false, destructiveHint: false, openWorldHint: false },
    executionMode: 'sequential',
    async execute(_id, params, signal, _onUpdate, ctx) {
      const flow = project(ctx);
      return result(await withFileMutationQueue(flow.guide, () => flow.propose(params, signal)));
    },
  });
}
